 private void renderRadarLoading(){if(radarRows==null)return;radarRows.removeAllViews();for(String s:radarSymbols){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);String[] a={s,"…","…","…"};for(int i=0;i<4;i++){TextView x=t(a[i],10,i==0?Color.WHITE:MUTED,i==0);x.setGravity(Gravity.CENTER);row.addView(x,new LinearLayout.LayoutParams(0,dp(34),1));}radarRows.addView(row);}}
 private String[] analyzeRadarSymbol(String s){try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(s,"6mo","1d",180);if(d==null||d.size()<35)return null;int n=d.size(),end=n-1;double price=d.get(end).close,prev=d.get(end-1).close,ma20=0,g=0,l=0,hi=-Double.MAX_VALUE,lo=Double.MAX_VALUE,tp=0,md=0;MarketDataService.Spot sp=MarketDataService.latestSpot(s);if(sp!=null&&sp.price>0)price=sp.price;for(int i=n-20;i<n;i++)ma20+=d.get(i).close;ma20/=20d;for(int i=n-14;i<n;i++){MarketDataService.Candle x=d.get(i);double z=x.close-d.get(i-1).close;if(z>=0)g+=z;else l-=z;hi=Math.max(hi,x.high);lo=Math.min(lo,x.low);tp+=(x.high+x.low+x.close)/3d;}double rsi=100-(100/(1+(l==0?100:g/l))),stoch=hi==lo?50:100*(price-lo)/(hi-lo),mtp=tp/14d;for(int i=n-14;i<n;i++){MarketDataService.Candle x=d.get(i);md+=Math.abs((x.high+x.low+x.close)/3d-mtp);}md/=14d;double cci=md==0?0:(((d.get(end).high+d.get(end).low+price)/3d)-mtp)/(0.015d*md),macd=ema(d,12,end)-ema(d,26,end),macdPrev=ema(d,12,end-1)-ema(d,26,end-1);int score=0;score+=price>ma20?1:-1;if(rsi<35)score++;else if(rsi>70)score--;if(macd>0&&macd>=macdPrev)score++;else if(macd<0&&macd<=macdPrev)score--;if(stoch<25)score++;else if(stoch>80)score--;if(cci>100)score++;else if(cci<-100)score--;int shortScore=score;double ma50=ema(d,50,end),ma100=ema(d,Math.min(100,n),end);int mediumScore=(price>ma20?1:-1)+(ma20>ma50?1:-1)+(macd>0?1:-1);int longScore=(price>ma50?1:-1)+(ma50>ma100?1:-1)+(cci>0?1:-1);String sig=score>=2?"AL":score<=-2?"SAT":"İZLE";String shortSig=shortScore>=2?"AL":shortScore<=-2?"SAT":"İZLE",mediumSig=mediumScore>=2?"AL":mediumScore<=-2?"SAT":"İZLE",longSig=longScore>=2?"AL":longScore<=-2?"SAT":"İZLE";int confidence=Math.min(95,50+Math.abs(score)*9);double pct=prev==0?0:(price-prev)/prev*100d;return new String[]{s,String.format(java.util.Locale.GERMANY,"%.2f",price),String.format(java.util.Locale.GERMANY,"%+.2f%%",pct),sig,String.valueOf(score),String.format(java.util.Locale.GERMANY,"Güven %d%% • Kısa %s • Orta %s • Uzun %s\nRSI %.0f • MACD %.2f • Stoch %.0f • CCI %.0f",confidence,shortSig,mediumSig,longSig,rsi,macd,stoch,cci),String.valueOf(confidence),shortSig,mediumSig,longSig};}catch(Exception ex){return null;}}
 private void loadRadarRows(){if(radarLoading)return;radarLoading=true;final String[] symbols=radarUniverse().clone();final java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(6);final java.util.concurrent.ConcurrentLinkedQueue<String[]> out=new java.util.concurrent.ConcurrentLinkedQueue<>();final java.util.concurrent.atomic.AtomicInteger done=new java.util.concurrent.atomic.AtomicInteger();for(String sym:symbols){pool.execute(()->{String[] row=analyzeRadarSymbol(sym);if(row!=null)out.add(row);int x=done.incrementAndGet();runOnUiThread(()->{if(radarProgress!=null&&screen==2)radarProgress.setText("Tarama: "+x+"/"+symbols.length+"  %"+Math.round(x*100f/symbols.length));});if(x==symbols.length){pool.shutdown();final java.util.ArrayList<String[]> result=new java.util.ArrayList<>(out);java.util.Collections.sort(result,(a,b)->Integer.compare(Integer.parseInt(b[4]),Integer.parseInt(a[4])));runOnUiThread(()->{radarLoading=false;cachedRadarRows.clear();cachedRadarRows.addAll(result);radarCacheByMarket.put(selectedMarket,new java.util.ArrayList<>(result));scanDone=true;scanDoneByMarket.put(selectedMarket,true);getSharedPreferences("borsaradar",MODE_PRIVATE).edit().putBoolean("scanDone_"+selectedMarket,true).apply();if(radarProgress!=null)radarProgress.setText("Tarama tamamlandı • "+result.size()+" hisse");renderRadarRows(cachedRadarRows);});}});}}
 private void renderRadarRows(java.util.List<String[]> rows){if(radarRows==null||screen!=2)return;radarRows.removeAllViews();for(String[] q:rows){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(2),dp(3),dp(2),dp(3));for(int i=0;i<4;i++){int col=i==2?(q[i].startsWith("-")?RED:GREEN):Color.WHITE;TextView x=i==3?pill(q[i]+(q.length>6?" "+q[6]+"%":""),q[i].equals("AL")?GREEN:q[i].equals("SAT")?RED:AMBER):t(q[i],10,col,i==0);x.setGravity(Gravity.CENTER);final String sym=q[0];if(i==0){x.setOnLongClickListener(v->{Toast.makeText(this,q.length>5?q[5]:"",Toast.LENGTH_LONG).show();return true;});x.setOnClickListener(v->{selectedSymbol=sym;lastRadarSymbol=sym;getSharedPreferences("borsaradar",MODE_PRIVATE).edit().putString("lastRadarSymbol",sym).apply();showDetail();});}row.addView(x,new LinearLayout.LayoutParams(0,dp(34),1));}radarRows.addView(row);}if(rows.isEmpty())radarRows.addView(t("Radar verisi alınamadı",11,RED,true));}
 private void loadLiveQuote(){ final String symbol=selectedSymbol; uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"5d","5m",400);if(d==null||d.size()<2)return;MarketDataService.Candle last=d.get(d.size()-1),prev=d.get(d.size()-2);double spot=last.close;MarketDataService.Spot sp=MarketDataService.latestSpot(symbol);if(sp!=null&&sp.price>0)spot=sp.price;double hi=last.high,lo=last.low,vol=last.volume; for(int i=Math.max(0,d.size()-80);i<d.size();i++){MarketDataService.Candle x=d.get(i);hi=Math.max(hi,x.high);lo=Math.min(lo,x.low);vol+=i==d.size()-1?0:x.volume;} final double price=spot,base=prev.close,chg=price-base,pct=base==0?0:(chg/base*100.0),open=last.open,high=hi,low=lo,volume=vol;final long tm=last.time;runOnUiThread(()->{if(!symbol.equals(selectedSymbol)||livePrice==null)return;livePrice.setText(String.format(java.util.Locale.GERMANY,"%.2f%s",price,currency(symbol)));liveChange.setText(String.format(java.util.Locale.GERMANY,"%+.2f  (%+.2f%%)",chg,pct));liveChange.setTextColor(chg>=0?GREEN:RED);liveTime.setText(new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm",java.util.Locale.GERMANY).format(new java.util.Date(tm*1000L))+" • "+MarketDataService.sourceFor(symbol,"5d","5m"));setLiveStats(new double[]{open,high,low,volume});});}catch(Exception e){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&livePrice!=null)livePrice.setText("Fiyat alınamadı");});}});}
 private double ema(java.util.List<MarketDataService.Candle>d,int p,int end){double k=2d/(p+1d),e=d.get(Math.max(0,end-p+1)).close;for(int i=Math.max(0,end-p+2);i<=end;i++)e=d.get(i).close*k+e*(1-k);return e;}
 private void loadComputedSignal(){final String symbol=selectedSymbol;uiIo.execute(()->{try{
  java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"6mo","1d",180);
  if(d==null||d.size()<35)return;
  ShortPulseEngine.Result p=ShortPulseEngine.analyze(d,symbol,selectedProfile);
  final String sig=p.recommendation.contains("SAT")?"SAT":p.recommendation.contains("AL")?"AL":"TUT";
  final String text=String.format(java.util.Locale.GERMANY,
    "Model: %s • Pulse %.1f • Güven %.0f%%\nBRTV %.1f • BRM %.2f • BRH %.1f\n%s",
    p.recommendation,p.score,p.confidence,p.brtv,p.brm,p.brh,p.phaseText);
  runOnUiThread(()->{if(!symbol.equals(selectedSymbol)||computedSignal==null)return;
    computedSignal.setText(text);computedSignal.setTextColor("AL".equals(sig)?GREEN:"SAT".equals(sig)?RED:AMBER);
  });
 }catch(Exception e){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&computedSignal!=null)computedSignal.setText("Sinyal hesaplanamadı");});}});}
