 private void loadRealChart(String period){
  final String[] range={"1d"},interval={"5m"};if("1H".equals(period)){range[0]="5d";interval[0]="5m";}else if("1A".equals(period)){range[0]="1mo";interval[0]="1d";}else if("3A".equals(period)){range[0]="3mo";interval[0]="1d";}else if("6A".equals(period)){range[0]="6mo";interval[0]="1d";}else if("1Y".equals(period)){range[0]="1y";interval[0]="1d";}else if("2Y".equals(period)){range[0]="2y";interval[0]="1d";}
  Toast.makeText(this,period+" verisi yükleniyor",Toast.LENGTH_SHORT).show();uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(selectedSymbol,range[0],interval[0],180);runOnUiThread(()->showLiveChart(period,d));}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Grafik verisi alınamadı",Toast.LENGTH_SHORT).show());}});
 }
